    def cluster_trunk_solution():
        """Two-level cluster/trunk multicast decomposition (edge-materialized).

        Clusters destinations (k = 1..min(8, |dsts|)) by greedy farthest-point
        initialization on the all-pairs shortest-path matrix of the
        symmetrized graph U. Per clustering, three deterministic gateway
        variants per cluster are tried (closest-to-src; cluster metric
        center; min sp(src,g)+max intra-cluster sp). Steiner trees
        (Dreyfus-Wagner when <=12 terminals, else networkx 2-approx) over
        {src}+gateways (trunk) and each cluster's terminals define the
        hierarchical structure. Crucially, every tree edge (u,v) is
        MATERIALIZED as a directed shortest path u->v in the original
        digraph h, so all dsts share the identical trunk node sequence
        (charged once by the exact directed union objective `sol_cost`)
        while every edge is traversed in its true direction — the flat
        pipeline's weakness on asymmetric costs. A bounded deterministic
        polish (marginal-cost splice passes over dsts, <=300 cheap
        evaluations) then tightens the plan. Best plan over all k and
        gateway variants is returned; the incumbent flat pipeline stays as
        the accept-only-if-better fallback.
        """
        from networkx.algorithms.approximation.steinertree import steiner_tree

        dst_list = [d for d in dsts if d != src and d in U]
        if not dst_list:
            return {}, float("inf")

        Uw = nx.Graph()
        for s, t, data in G.edges(data=True):
            if s == t or data.get("cost") is None:
                continue
            w = data["cost"]
            if Uw.has_edge(s, t):
                Uw[s][t]["cost"] = min(Uw[s][t]["cost"], w)
            else:
                Uw.add_edge(s, t, cost=w)

        def solve_st(terms):
            if len(terms) <= 1:
                return None
            try:
                if not nx.is_connected(Uw.subgraph(Uw.nodes)):
                    return None
                if len(terms) <= 12:
                    return exact_steiner_tree(Uw, terms)
                return steiner_tree(Uw, terms, weight="cost")
            except Exception:
                return None

        try:
            D = dict(nx.all_pairs_dijkstra_path_length(U, weight="cost"))
        except Exception:
            return {}, float("inf")

        def sp(a, b):
            return D.get(a, {}).get(b, math.inf)

        # Cache of directed shortest paths between arbitrary node pairs in h.
        dir_cache = {}

        def dir_path(o, d):
            key = (o, d)
            if key not in dir_cache:
                try:
                    dir_cache[key] = nx.dijkstra_path(h, o, d, weight="cost")
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    dir_cache[key] = None
            return dir_cache[key]

        def materialize(tree, root):
            """Orient `tree` from `root` and return parent map where each
            tree edge is expanded into a directed path in h (prefix of the
            parent's expanded path is reused, so sharing is preserved)."""
            par = {root: None}
            order = [root]
            for node in order:
                for nb in tree[node]:
                    if nb in par:
                        continue
                    seg = dir_path(node, nb)
                    if seg is None or len(seg) < 2:
                        return None
                    prev = node
                    for v in seg[1:]:
                        par[v] = prev
                        prev = v
                    order.extend(seg[1:])
            return par

        def tree_path(par, node):
            pn = []
            while node is not None:
                pn.append(node)
                node = par[node]
            return pn[::-1]

        def polish(pmap, rounds=3):
            """Deterministic marginal-cost polish: for each dst, splice its
            suffix onto another dst's shared prefix if it strictly lowers
